CREATE TYPE public.fanmap_role AS ENUM ('fan','artist');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Fan', username text UNIQUE, bio text NOT NULL DEFAULT '', avatar_path text, social_links jsonb NOT NULL DEFAULT '{}', preferences jsonb NOT NULL DEFAULT '{"announcements":true,"friendRequests":true,"publicProfile":false,"notifications":true}', is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_self_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid()); CREATE POLICY profile_self_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.fanmap_role NOT NULL DEFAULT 'fan', artist_id text);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY role_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.fanmap_artist(a text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='artist' AND artist_id=a) $$;
CREATE FUNCTION public.fanmap_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','Fan')); INSERT INTO public.user_roles(user_id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER fanmap_new_user AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.fanmap_signup();
CREATE TABLE public.events(id text PRIMARY KEY, artist_id text NOT NULL, artist_name text NOT NULL, venue text NOT NULL, city text NOT NULL, starts_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'America/Toronto', ticket_code text NOT NULL, checkin_code text NOT NULL, outcomes jsonb, is_demo boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.events TO authenticated; GRANT ALL ON public.events TO service_role; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY; CREATE POLICY event_read ON public.events FOR SELECT TO authenticated USING(true);
CREATE TABLE public.tickets(user_id uuid NOT NULL REFERENCES public.profiles(id), event_id text NOT NULL REFERENCES public.events(id), PRIMARY KEY(user_id,event_id)); GRANT SELECT ON public.tickets TO authenticated; GRANT ALL ON public.tickets TO service_role; ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY; CREATE POLICY tickets_self ON public.tickets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), event_id text NOT NULL REFERENCES public.events(id), attended_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_id)); GRANT SELECT ON public.attendance TO authenticated; GRANT ALL ON public.attendance TO service_role; ALTER TABLE public.attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY attendance_access ON public.attendance FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.fanmap_artist((SELECT artist_id FROM public.events WHERE id=event_id)));
CREATE FUNCTION public.fanmap_eligible(e text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.attendance WHERE user_id=auth.uid() AND event_id=e) OR (EXISTS(SELECT 1 FROM public.events WHERE id=e AND starts_at>=date_trunc('day',now())) AND EXISTS(SELECT 1 FROM public.tickets WHERE user_id=auth.uid() AND event_id=e)) $$;
CREATE FUNCTION public.fanmap_verified() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='fan') AND (EXISTS(SELECT 1 FROM public.tickets WHERE user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.attendance WHERE user_id=auth.uid())) $$;
CREATE FUNCTION public.fanmap_verify(code text, checkin boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.events; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO e FROM public.events WHERE (CASE WHEN checkin THEN checkin_code ELSE ticket_code END)=upper(trim(code)); IF e.id IS NULL THEN RAISE EXCEPTION 'Invalid demonstration code'; END IF; IF NOT e.is_demo THEN RAISE EXCEPTION 'Ticket provider verification is required'; END IF; IF checkin THEN IF NOT EXISTS(SELECT 1 FROM public.tickets WHERE user_id=auth.uid() AND event_id=e.id) THEN RAISE EXCEPTION 'Verify your ticket first'; END IF; IF (e.starts_at AT TIME ZONE e.timezone)::date<>(now() AT TIME ZONE e.timezone)::date THEN RAISE EXCEPTION 'Check-in opens on concert day only'; END IF; INSERT INTO public.attendance(user_id,event_id) VALUES(auth.uid(),e.id); ELSE IF e.starts_at<now() THEN RAISE EXCEPTION 'This concert ticket window has closed'; END IF; INSERT INTO public.tickets VALUES(auth.uid(),e.id); END IF; RETURN e.id; END $$;
CREATE TABLE public.letters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id text NOT NULL REFERENCES public.events(id), user_id uuid NOT NULL REFERENCES public.profiles(id), text text NOT NULL CHECK(length(text) BETWEEN 1 AND 1000), featured boolean NOT NULL DEFAULT false, artist_reply text, show_count boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.letters TO authenticated; GRANT ALL ON public.letters TO service_role; ALTER TABLE public.letters ENABLE ROW LEVEL SECURITY; CREATE POLICY letters_read ON public.letters FOR SELECT TO authenticated USING(public.fanmap_eligible(event_id) OR user_id=auth.uid() OR public.fanmap_artist((SELECT artist_id FROM public.events WHERE id=event_id))); CREATE POLICY letters_add ON public.letters FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.fanmap_eligible(event_id) AND NOT featured AND artist_reply IS NULL); CREATE POLICY letters_delete ON public.letters FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.letter_likes(letter_id uuid NOT NULL REFERENCES public.letters(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id),PRIMARY KEY(letter_id,user_id)); GRANT SELECT,INSERT,DELETE ON public.letter_likes TO authenticated; GRANT ALL ON public.letter_likes TO service_role; ALTER TABLE public.letter_likes ENABLE ROW LEVEL SECURITY; CREATE POLICY likes_read ON public.letter_likes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.letters WHERE id=letter_id)); CREATE POLICY likes_add ON public.letter_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.letters WHERE id=letter_id AND public.fanmap_eligible(event_id))); CREATE POLICY likes_delete ON public.letter_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.reels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id text NOT NULL REFERENCES public.events(id),user_id uuid NOT NULL REFERENCES public.profiles(id),path text NOT NULL,caption text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),duration numeric NOT NULL CHECK(duration>0 AND duration<=10),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.reels TO authenticated; GRANT ALL ON public.reels TO service_role; ALTER TABLE public.reels ENABLE ROW LEVEL SECURITY; CREATE POLICY reels_read ON public.reels FOR SELECT TO authenticated USING(user_id=auth.uid() OR (status='approved' AND public.fanmap_eligible(event_id)) OR public.fanmap_artist((SELECT artist_id FROM public.events WHERE id=event_id))); CREATE POLICY reels_submit ON public.reels FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND path LIKE auth.uid()::text||'/%' AND public.fanmap_eligible(event_id) AND EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND starts_at+interval '4 hours'>now()));
CREATE TABLE public.reel_votes(user_id uuid NOT NULL REFERENCES public.profiles(id),event_id text NOT NULL REFERENCES public.events(id),reel_id uuid NOT NULL REFERENCES public.reels(id),PRIMARY KEY(user_id,event_id)); GRANT SELECT,INSERT ON public.reel_votes TO authenticated; GRANT ALL ON public.reel_votes TO service_role; ALTER TABLE public.reel_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY votes_read ON public.reel_votes FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY votes_add ON public.reel_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.fanmap_eligible(event_id) AND EXISTS(SELECT 1 FROM public.reels WHERE id=reel_id AND event_id=reel_votes.event_id AND status='approved') AND EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND starts_at+interval '4 hours'>now()));
CREATE TABLE public.predictions(user_id uuid NOT NULL REFERENCES public.profiles(id),event_id text NOT NULL REFERENCES public.events(id),answers jsonb NOT NULL DEFAULT '{}',locked boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,event_id)); GRANT SELECT,INSERT,UPDATE ON public.predictions TO authenticated; GRANT ALL ON public.predictions TO service_role; ALTER TABLE public.predictions ENABLE ROW LEVEL SECURITY; CREATE POLICY predictions_self ON public.predictions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY predictions_add ON public.predictions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.fanmap_eligible(event_id) AND EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND starts_at>now())); CREATE POLICY predictions_update ON public.predictions FOR UPDATE TO authenticated USING(user_id=auth.uid() AND NOT locked AND EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND starts_at>now())) WITH CHECK(user_id=auth.uid() AND public.fanmap_eligible(event_id));
CREATE TABLE public.deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES public.profiles(id),artist_id text NOT NULL,sender_id uuid NOT NULL REFERENCES public.profiles(id),text text NOT NULL,media_path text,media_type text,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz); GRANT SELECT,UPDATE ON public.deliveries TO authenticated; GRANT ALL ON public.deliveries TO service_role; ALTER TABLE public.deliveries ENABLE ROW LEVEL SECURITY; CREATE POLICY deliveries_self ON public.deliveries FOR SELECT TO authenticated USING(recipient_id=auth.uid() OR public.fanmap_artist(artist_id));
CREATE TABLE public.reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),letter_id uuid REFERENCES public.letters(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT INSERT,SELECT ON public.reports TO authenticated; GRANT ALL ON public.reports TO service_role; ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY; CREATE POLICY reports_add ON public.reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid()); CREATE POLICY reports_self ON public.reports FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.deletion_requests(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now()); GRANT INSERT,SELECT ON public.deletion_requests TO authenticated; GRANT ALL ON public.deletion_requests TO service_role; ALTER TABLE public.deletion_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY deletion_self ON public.deletion_requests TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.fanmap_edit_letter(l uuid,body text DEFAULT NULL,feature boolean DEFAULT NULL,reply text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.letters; BEGIN SELECT * INTO x FROM public.letters WHERE id=l; IF x.id IS NULL THEN RAISE EXCEPTION 'Letter not found'; END IF; IF feature IS NOT NULL OR reply IS NOT NULL THEN IF NOT public.fanmap_artist((SELECT artist_id FROM public.events WHERE id=x.event_id)) THEN RAISE EXCEPTION 'Artist permission required'; END IF; UPDATE public.letters SET featured=coalesce(feature,featured),artist_reply=coalesce(reply,artist_reply) WHERE id=l; ELSE IF x.user_id<>auth.uid() THEN RAISE EXCEPTION 'You can edit only your own letter'; END IF; UPDATE public.letters SET text=body WHERE id=l; END IF; END $$;
CREATE FUNCTION public.fanmap_moderate(r uuid,s text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.reels JOIN public.events ON events.id=reels.event_id WHERE reels.id=r AND public.fanmap_artist(events.artist_id)) THEN RAISE EXCEPTION 'Artist permission required'; END IF; UPDATE public.reels SET status=s WHERE id=r; END $$;
REVOKE ALL ON FUNCTION public.fanmap_verify(text,boolean),public.fanmap_edit_letter(uuid,text,boolean,text),public.fanmap_moderate(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.fanmap_verify(text,boolean),public.fanmap_edit_letter(uuid,text,boolean,text),public.fanmap_moderate(uuid,text) TO authenticated;